import fs from 'node:fs/promises';
const headers={apikey:process.env.SUPABASE_KEY,Authorization:'Bearer '+process.env.SUPABASE_KEY,'Content-Type':'application/json',Prefer:'return=representation'};
async function db(table,q,method='GET',body){const r=await fetch(process.env.SUPABASE_URL+'/rest/v1/'+table+'?'+new URLSearchParams(q),{method,headers,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(table+' '+r.status);return r.json();}
const reviews=[
{id:'0ab14a7c-ba8b-4cf6-b0e9-116d1bcde2d9',title:'Deliver Amanda’s requested AMANDA15 digital card',next_action:'Amanda accepted the digital card. Branded self-contained HTML prepared at partnership-system/exports/amanda15/Amanda-Lawson-AMANDA15.html. Export/share through the existing approved channel during business hours. Do not ask again whether she wants a card. Grandma move remains unconfirmed.',source:'market_touches:27ed0d91-b610-4366-84bf-49b3d76619ac',due_at:'2026-09-16T13:00:00Z'},
{id:'53fb9d89-0871-4c67-aef6-bd789d8c990e',title:'Mark — await next week’s presentation availability',next_action:'Mark replied that he will check about next week and get back to John. Await that response. September 18 is an internal review, not an automatic reminder. No new presentation date confirmed.',source:'market_touches:befa4e78-1ee9-4aec-980c-f061aa24b328'},
{id:'474355a0-2cf9-46f9-a325-fafa6e58479d',next_action:'Facilities official page confirms corporate facility operations but publishes no direct contact. Official Community Services page publishes parkrec@citywindsor.ca / 519-253-2300 as its detailed-inquiry route; treat as a routing fallback, not a verified named Facilities buyer. Purchasing has already replied and been thanked. Next ask the official routing desk for Facilities moving/furniture support contact with Purchasing context; do not guess personal addresses or contact unrelated construction officials.',source:'https://www.citywindsor.ca/city-hall/city-departments/public-works/facilities',routing_source:'https://www.citywindsor.ca/city-hall/city-departments/office-of-the-commissioner-of-community-and-corporate-services'},
{id:'1a53f752-23d1-48b5-bcfc-0b0697616d45',next_action:'Official starmovers.ca homepage checked September 16; no official Facebook/Instagram links exposed in page. Search did not establish ownership. Preserve promise; obtain confirmed brand-account URLs before sending. Do not use guessed social handles.',source:'https://starmovers.ca'}];
const receipt=[];
for(const review of reviews){const [old]=await db('crm_tasks',{id:'eq.'+review.id});if(!old)throw Error('Missing task '+review.id);let prior;try{prior=JSON.parse(old.description)}catch{}
if(prior?.review_key==='20260916-followthrough-v1'){receipt.push({id:review.id,status:'already_updated'});continue;}
const {id,title,due_at,...evidence}=review;
const patch={description:JSON.stringify({...evidence,review_key:'20260916-followthrough-v1',reviewed_at:new Date().toISOString(),previous_description:old.description}),...(title?{title}:{}),...(due_at?{due_at}:{} )};
await db('crm_tasks',{id:'eq.'+id,description:'eq.'+old.description},'PATCH',patch).then(rows=>{if(rows.length!==1)throw Error('Concurrent task change: '+id)});receipt.push({id,status:'updated'});}
await fs.writeFile('partnership-system/state/followthrough-review-20260916.json',JSON.stringify({at:new Date().toISOString(),receipt,reviews},null,2));console.log(JSON.stringify(receipt));
